     1	package br.com.marealta;
     2	
     3	import com.fasterxml.jackson.core.JsonProcessingException;
     4	import com.fasterxml.jackson.databind.JsonNode;
     5	import com.fasterxml.jackson.databind.ObjectMapper;
     6	import com.fasterxml.jackson.databind.SerializationFeature;
     7	import com.fasterxml.jackson.core.JsonGenerator;
     8	import io.javalin.Javalin;
     9	import io.javalin.http.Context;
    10	
    11	import java.time.LocalDate;
    12	import java.time.YearMonth;
    13	import java.time.format.DateTimeParseException;
    14	import java.util.ArrayList;
    15	import java.util.LinkedHashMap;
    16	import java.util.List;
    17	import java.util.Map;
    18	
    19	final class Api {
    20	    private static final ObjectMapper JSON = new ObjectMapper()
    21	            .configure(JsonGenerator.Feature.WRITE_BIGDECIMAL_AS_PLAIN, true)
    22	            .disable(SerializationFeature.FAIL_ON_EMPTY_BEANS);
    23	
    24	    private final ReservationService service;
    25	    private final Outbox outbox;
    26	
    27	    Api(ReservationService service, Outbox outbox) {
    28	        this.service = service;
    29	        this.outbox = outbox;
    30	    }
    31	
    32	    Javalin create() {
    33	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    34	
    35	        app.exception(ApiException.class, (e, ctx) -> error(ctx, e.status, e.code, e.getMessage()));
    36	        app.exception(Exception.class, (e, ctx) -> error(ctx, 500, "INTERNAL_ERROR", "Erro interno"));
    37	        app.error(404, ctx -> {
    38	            if (ctx.result() == null || ctx.result().isEmpty()) {
    39	                error(ctx, 404, "NOT_FOUND", "Recurso não encontrado");
    40	            }
    41	        });
    42	
    43	        app.get("/rooms", ctx -> json(ctx, 200, Room.ALL.stream().map(Api::roomView).toList()));
    44	        app.post("/reservations", ctx -> json(ctx, 201, reservationView(service.create(parseNew(ctx)))));
    45	        app.get("/reservations/{id}", ctx -> json(ctx, 200, reservationView(service.get(ctx.pathParam("id")))));
    46	        app.post("/reservations/{id}/confirmation",
    47	                ctx -> json(ctx, 200, reservationView(service.confirm(ctx.pathParam("id")))));
    48	        app.post("/reservations/{id}/cancellation",
    49	                ctx -> json(ctx, 200, reservationView(service.cancel(ctx.pathParam("id")))));
    50	        app.post("/reservations/{id}/check-in",
    51	                ctx -> json(ctx, 200, reservationView(service.checkIn(ctx.pathParam("id")))));
    52	        app.post("/reservations/{id}/check-out",
    53	                ctx -> json(ctx, 200, documentView(service.checkOut(ctx.pathParam("id")))));
    54	        app.get("/reservations/{id}/document",
    55	                ctx -> json(ctx, 200, documentView(service.duplicate(ctx.pathParam("id")))));
    56	        app.get("/messages", ctx -> json(ctx, 200, outbox.all().stream().map(Api::messageView).toList()));
    57	        app.get("/reports/occupancy", ctx -> {
    58	            LocalDate date = date(ctx.queryParam("date"), "date");
    59	            csv(ctx, Reports.occupancy(service.all(), date));
    60	        });
    61	        app.get("/reports/revenue", ctx -> {
    62	            String m = ctx.queryParam("month");
    63	            YearMonth month;
    64	            try {
    65	                if (m == null) throw new DateTimeParseException("missing", "", 0);
    66	                month = YearMonth.parse(m);
    67	            } catch (DateTimeParseException e) {
    68	                throw ApiException.invalid("month deve estar no formato AAAA-MM");
    69	            }
    70	            csv(ctx, Reports.revenue(service.all(), month));
    71	        });
    72	        return app;
    73	    }
    74	
    75	    // ---- request parsing ----
    76	
    77	    private ReservationService.NewReservation parseNew(Context ctx) {
    78	        JsonNode body;
    79	        try {
    80	            body = JSON.readTree(ctx.bodyAsBytes());
    81	        } catch (java.io.IOException e) {
    82	            throw ApiException.invalid("Corpo da requisição não é um JSON válido");
    83	        }
    84	        if (body == null || !body.isObject()) {
    85	            throw ApiException.invalid("Corpo da requisição deve ser um objeto JSON");
    86	        }
    87	        String name = requiredText(body, "guestName");
    88	        String email = requiredText(body, "guestEmail");
    89	        LocalDate checkIn = date(optionalText(body, "checkIn"), "checkIn");
    90	        LocalDate checkOut = date(optionalText(body, "checkOut"), "checkOut");
    91	        JsonNode roomNode = body.get("roomNumber");
    92	        if (roomNode == null || !roomNode.isIntegralNumber() || !roomNode.canConvertToInt()) {
    93	            throw ApiException.invalid("roomNumber é obrigatório e deve ser inteiro");
    94	        }
    95	        JsonNode guestsNode = body.get("guests");
    96	        if (guestsNode == null || !guestsNode.isIntegralNumber() || !guestsNode.canConvertToInt()) {
    97	            throw ApiException.invalid("guests é obrigatório e deve ser inteiro");
    98	        }
    99	        RatePlan plan;
   100	        try {
   101	            plan = RatePlan.valueOf(requiredText(body, "ratePlan"));
   102	        } catch (IllegalArgumentException e) {
   103	            throw ApiException.invalid("ratePlan deve ser STANDARD ou NON_REFUNDABLE");
   104	        }
   105	        if (!checkOut.isAfter(checkIn)) {
   106	            throw ApiException.invalid("checkOut deve ser depois de checkIn");
   107	        }
   108	        if (guestsNode.intValue() < 1) {
   109	            throw ApiException.invalid("guests deve ser pelo menos 1");
   110	        }
   111	        return new ReservationService.NewReservation(roomNode.intValue(), name, email, identification(body),
   112	                checkIn, checkOut, guestsNode.intValue(), plan);
   113	    }
   114	
   115	    private static Identification identification(JsonNode body) {
   116	        String cpf = optionalText(body, "guestCpf");
   117	        String cnpj = optionalText(body, "companyCnpj");
   118	        String company = optionalText(body, "companyName");
   119	        String passport = optionalText(body, "guestPassport");
   120	        String country = optionalText(body, "guestCountry");
   121	        boolean isCpf = cpf != null;
   122	        boolean isCnpj = cnpj != null && company != null;
   123	        boolean isPassport = passport != null && country != null;
   124	        int provided = (cpf != null ? 1 : 0) + (cnpj != null ? 1 : 0) + (company != null ? 1 : 0)
   125	                + (passport != null ? 1 : 0) + (country != null ? 1 : 0);
   126	        int expected = isCpf ? 1 : isCnpj ? 2 : isPassport ? 2 : -1;
   127	        boolean single = (isCpf ? 1 : 0) + (isCnpj ? 1 : 0) + (isPassport ? 1 : 0) == 1;
   128	        if (!single || provided != expected) {
   129	            throw ApiException.invalid("Informe exatamente um: guestCpf; companyCnpj com companyName; "
   130	                    + "ou guestPassport com guestCountry");
   131	        }
   132	        if (isCpf) return new Identification.Cpf(cpf);
   133	        if (isCnpj) return new Identification.Cnpj(cnpj, company);
   134	        return new Identification.Passport(passport, country);
   135	    }
   136	
   137	    /** Null when missing, null or blank; 400 when present but not a string. */
   138	    private static String optionalText(JsonNode body, String field) {
   139	        JsonNode n = body.get(field);
   140	        if (n == null || n.isNull()) return null;
   141	        if (!n.isTextual()) throw ApiException.invalid(field + " deve ser texto");
   142	        String s = n.textValue().strip();
   143	        return s.isEmpty() ? null : s;
   144	    }
   145	
   146	    private static String requiredText(JsonNode body, String field) {
   147	        String s = optionalText(body, field);
   148	        if (s == null) throw ApiException.invalid(field + " é obrigatório");
   149	        return s;
   150	    }
   151	
   152	    private static LocalDate date(String value, String field) {
   153	        if (value == null) throw ApiException.invalid(field + " é obrigatório (formato AAAA-MM-DD)");
   154	        try {
   155	            return LocalDate.parse(value);
   156	        } catch (DateTimeParseException e) {
   157	            throw ApiException.invalid(field + " deve estar no formato AAAA-MM-DD");
   158	        }
   159	    }
   160	
   161	    // ---- views ----
   162	
   163	    private static Map<String, Object> roomView(Room r) {
   164	        Map<String, Object> m = new LinkedHashMap<>();
   165	        m.put("number", r.number());
   166	        m.put("type", r.type());
   167	        m.put("capacity", r.capacity());
   168	        m.put("nightlyRate", r.nightlyRate());
   169	        return m;
   170	    }
   171	
   172	    private static void putIdentification(Map<String, Object> m, Identification id) {
   173	        m.put("guestCpf", id instanceof Identification.Cpf c ? c.cpf() : null);
   174	        m.put("companyCnpj", id instanceof Identification.Cnpj c ? c.cnpj() : null);
   175	        m.put("companyName", id instanceof Identification.Cnpj c ? c.companyName() : null);
   176	        m.put("guestPassport", id instanceof Identification.Passport p ? p.passport() : null);
   177	        m.put("guestCountry", id instanceof Identification.Passport p ? p.country() : null);
   178	    }
   179	
   180	    private static Map<String, Object> reservationView(Reservation r) {
   181	        Map<String, Object> m = new LinkedHashMap<>();
   182	        m.put("id", r.id);
   183	        m.put("roomNumber", r.room.number());
   184	        m.put("guestName", r.guestName);
   185	        m.put("guestEmail", r.guestEmail);
   186	        putIdentification(m, r.identification);
   187	        m.put("checkIn", r.checkIn.toString());
   188	        m.put("checkOut", r.checkOut.toString());
   189	        m.put("guests", r.guests);
   190	        m.put("ratePlan", r.ratePlan);
   191	        m.put("nights", r.quote.nights());
   192	        m.put("subtotal", r.quote.subtotal());
   193	        m.put("discount", r.quote.discount());
   194	        m.put("total", r.quote.total());
   195	        m.put("status", r.status);
   196	        m.put("amountPaid", r.amountPaid);
   197	        m.put("refund", r.refund);
   198	        return m;
   199	    }
   200	
   201	    private static Map<String, Object> documentView(Document d) {
   202	        Map<String, Object> m = new LinkedHashMap<>();
   203	        m.put("title", d.title());
   204	        m.put("reservationId", d.reservationId());
   205	        m.put("guestName", d.guestName());
   206	        putIdentification(m, d.identification());
   207	        m.put("roomNumber", d.room().number());
   208	        m.put("roomType", d.room().type());
   209	        m.put("checkIn", d.checkIn().toString());
   210	        m.put("checkOut", d.checkOut().toString());
   211	        m.put("nights", d.nights());
   212	        m.put("subtotal", d.subtotal());
   213	        m.put("discount", d.discount());
   214	        m.put("total", d.total());
   215	        m.put("text", d.text());
   216	        return m;
   217	    }
   218	
   219	    private static Map<String, Object> messageView(Message msg) {
   220	        Map<String, Object> m = new LinkedHashMap<>();
   221	        m.put("id", msg.id());
   222	        m.put("channel", msg.channel());
   223	        m.put("to", msg.to());
   224	        m.put("subject", msg.subject());
   225	        m.put("body", msg.body());
   226	        return m;
   227	    }
   228	
   229	    // ---- responses ----
   230	
   231	    private static void json(Context ctx, int status, Object body) {
   232	        try {
   233	            ctx.status(status).contentType("application/json").result(JSON.writeValueAsString(body));
   234	        } catch (JsonProcessingException e) {
   235	            throw new IllegalStateException(e);
   236	        }
   237	    }
   238	
   239	    private static void csv(Context ctx, String body) {
   240	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
   241	    }
   242	
   243	    private static void error(Context ctx, int status, String code, String message) {
   244	        Map<String, Object> m = new LinkedHashMap<>();
   245	        m.put("error", code);
   246	        m.put("message", message);
   247	        json(ctx, status, m);
   248	    }
   249	}

