     8	final class ReservationService {
     9	    static final String CONFIRMATION_SUBJECT = "Reserva confirmada - Pousada Maré Alta";
    10	
    11	    private final List<Reservation> reservations = new ArrayList<>();
    12	    private final Outbox outbox;
    13	
    14	    ReservationService(Outbox outbox) {
    15	        this.outbox = outbox;
    16	    }
    17	
    18	    record NewReservation(int roomNumber, String guestName, String guestEmail, Identification identification,
    19	                          LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) {}
    20	
    21	    synchronized Reservation create(NewReservation n) {
    22	        Room room = Room.ALL.stream().filter(r -> r.number() == n.roomNumber()).findFirst()
    23	                .orElseThrow(() -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + n.roomNumber() + " não existe"));
    24	        if (n.guests() > room.capacity()) {
    25	            throw new ApiException(422, "CAPACITY_EXCEEDED",
    26	                    "O quarto " + room.number() + " comporta até " + room.capacity() + " hóspedes");
    27	        }
    28	        boolean taken = reservations.stream().anyMatch(r -> r.room.equals(room)
    29	                && r.status != Status.CANCELLED && r.overlaps(n.checkIn(), n.checkOut()));
    30	        if (taken) {
    31	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Quarto já reservado em alguma das noites pedidas");
    32	        }
    33	        Pricing.Quote quote = Pricing.quote(room, n.checkIn(), n.checkOut(), n.ratePlan());
    34	        Reservation r = new Reservation(reservations.size() + 1, room, n.guestName(), n.guestEmail(),
    35	                n.identification(), n.checkIn(), n.checkOut(), n.guests(), n.ratePlan(), quote);
    36	        reservations.add(r);
    37	        return r;
    38	    }
    39	
    40	    synchronized Reservation get(String id) {
    41	        try {
    42	            int i = Integer.parseInt(id);
    43	            if (i >= 1 && i <= reservations.size()) {
    44	                return reservations.get(i - 1);
    45	            }
    46	        } catch (NumberFormatException ignored) {
    47	            // falls through to not found
    48	        }
    49	        throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe");
    50	    }
    51	
    52	    synchronized Reservation confirm(String id) {
    53	        Reservation r = get(id);
    54	        require(r, "confirmar", Status.PENDING);
    55	        r.status = Status.CONFIRMED;
    56	        r.amountPaid = r.quote.total();
    57	        String doc = Documents.render(r).text();
    58	        String body = "Olá, " + r.guestName + "!\n\n"
    59	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
    60	                + doc + "\n\n"
    61	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
    62	                + "Até breve!";
    63	        outbox.sendEmail(r.guestEmail, CONFIRMATION_SUBJECT, body);
    64	        return r;
    65	    }
    66	
    67	    synchronized Reservation cancel(String id) {
    68	        Reservation r = get(id);
    69	        require(r, "cancelar", Status.PENDING, Status.CONFIRMED);
    70	        r.refund = r.ratePlan == RatePlan.STANDARD ? r.amountPaid : Money.ZERO;
    71	        r.status = Status.CANCELLED;
    72	        return r;
    73	    }
    74	
    75	    synchronized Reservation checkIn(String id) {
    76	        Reservation r = get(id);
    77	        require(r, "fazer check-in de", Status.CONFIRMED);
    78	        r.status = Status.CHECKED_IN;
    79	        return r;
    80	    }
    81	
    82	    synchronized Document checkOut(String id) {
    83	        Reservation r = get(id);
    84	        require(r, "fazer check-out de", Status.CHECKED_IN);
    85	        r.status = Status.CHECKED_OUT;
    86	        return Documents.render(r);
    87	    }
    88	
    89	    synchronized Document duplicate(String id) {
    90	        Reservation r = get(id);
    91	        if (!r.status.isPaid()) {
    92	            throw new ApiException(409, "OPERATION_NOT_ALLOWED",
    93	                    "Segunda via só existe para reserva paga; situação atual: " + r.status);
    94	        }
    95	        return Documents.render(r);
    96	    }
    97	
    98	    synchronized List<Reservation> all() {
    99	        return List.copyOf(reservations);
   100	    }
   101	
   102	    private static void require(Reservation r, String action, Status... allowed) {
   103	        for (Status s : allowed) {
   104	            if (r.status == s) {
   105	                return;
   106	            }
   107	        }
   108	        throw new ApiException(409, "OPERATION_NOT_ALLOWED",
   109	                "Não é possível " + action + " reserva com situação " + r.status);
   110	    }
