     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	/** Monetary helpers: every amount is rounded to cents, half-even. */
    10	final class Money {
    11	    static final BigDecimal ZERO = round(BigDecimal.ZERO);
    12	
    13	    private Money() {}
    14	
    15	    static BigDecimal round(BigDecimal v) {
    16	        return v.setScale(2, RoundingMode.HALF_EVEN);
    17	    }
    18	
    19	    static BigDecimal of(String v) {
    20	        return round(new BigDecimal(v));
    21	    }
    22	
    23	    /** R$ 1.234,56 */
    24	    static String brl(BigDecimal v) {
    25	        return "R$ " + format(v, ',', '.');
    26	    }
    27	
    28	    /** BRL 1,234.56 */
    29	    static String brlEn(BigDecimal v) {
    30	        return "BRL " + format(v, '.', ',');
    31	    }
    32	
    33	    /** 1234.56, for CSV. */
    34	    static String plain(BigDecimal v) {
    35	        return round(v).toPlainString();
    36	    }
    37	
    38	    private static String format(BigDecimal v, char decimal, char grouping) {
    39	        DecimalFormatSymbols s = DecimalFormatSymbols.getInstance(Locale.ROOT);
