     1	package br.com.marealta;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	final class Pricing {
     7	    private static final BigDecimal HIGH_SEASON = new BigDecimal("1.20");
     8	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
     9	
    10	    private Pricing() {}
    11	
    12	    record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    13	
    14	    /** 15/12 to end of February, and all of July. */
    15	    static boolean highSeason(LocalDate night) {
    16	        int m = night.getMonthValue();
    17	        return m == 1 || m == 2 || m == 7 || (m == 12 && night.getDayOfMonth() >= 15);
    18	    }
    19	
    20	    static BigDecimal nightPrice(Room room, LocalDate night) {
    21	        BigDecimal rate = room.nightlyRate();
    22	        return highSeason(night) ? Money.round(rate.multiply(HIGH_SEASON)) : Money.round(rate);
    23	    }
    24	
    25	    static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    26	        BigDecimal subtotal = Money.ZERO;
    27	        int nights = 0;
    28	        for (LocalDate d = checkIn; d.isBefore(checkOut); d = d.plusDays(1)) {
    29	            subtotal = Money.round(subtotal.add(nightPrice(room, d)));
    30	            nights++;
    31	        }
    32	        BigDecimal discount = plan == RatePlan.NON_REFUNDABLE
    33	                ? Money.round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT))
    34	                : Money.ZERO;
    35	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    36	    }
    37	}
